    centeredText(g, i, cellCenterX(i), 66, 40, '#000', false);
  }

  g.text('next').font(serif(52, true)).fill('#000')
    .attr({ 'text-anchor':'end', 'dominant-baseline':'middle' }).center(tableX - 68, cellCenterY(0));
  g.text('key').font(serif(52, true)).fill('#000')
    .attr({ 'text-anchor':'end', 'dominant-baseline':'middle' }).center(tableX - 69, cellCenterY(1));
  g.text('prev').font(serif(52, true)).fill('#000')
    .attr({ 'text-anchor':'end', 'dominant-baseline':'middle' }).center(tableX - 68, cellCenterY(2));

  for (i = 1; i <= 10; i++) {
    rec = data.records[i];
    var txtColor = rec.role === 'free' ? '#fff' : '#000';

    if (rec.next === null) {
      drawSlash(g, i, 0, txtColor, rec.role === 'free' ? 6 : 4);
    } else if (rec.next !== undefined) {
      centeredText(g, rec.next, cellCenterX(i), cellCenterY(0) + 1, 50, txtColor, false)
        .font({ weight: rec.role === 'free' ? 'bold' : 'normal' });
    }

    if (rec.key) {
      centeredText(g, rec.key, cellCenterX(i), cellCenterY(1) + 3, 45, '#000', true);
    }

    if (rec.prev === null) {
      drawSlash(g, i, 2, txtColor, rec.role === 'free' ? 6 : 4);
    } else if (rec.prev !== undefined) {
      centeredText(g, rec.prev, cellCenterX(i), cellCenterY(2) + 1, 50, txtColor, false);
    }
  }

  drawPointerHitCells(g, data);
}

function drawPointerHitCells(g, data) {
  for (var i = 1; i <= 10; i++) {
    var rec = data.records[i];
    addPointerHit(g, i, 0, rec.next, 'next');
    if (rec.prev !== undefined) addPointerHit(g, i, 2, rec.prev, 'prev');
  }
}

function addPointerHit(g, col, row, value, field) {
  var x = colX(col), y = tableY + row * rowH;
  var hit = g.rect(colW, rowH).move(x, y).fill('#fff').opacity(0)
    .attr({ 'pointer-events':'all' }).css('cursor','pointer');

  hit.on('mousemove', function(e) {
    hoverPointer(col, row, value, field);
    if (value === null) {
      showTooltip('The ' + field + ' field at index ' + col + ' is NIL: the chain stops here.', e);
    } else {
      showTooltip('The ' + field + ' field at index ' + col + ' stores ' + value + ', so it points to array index ' + value + '.', e);
    }
  }).on('mouseleave', function() {
    hoverGroup.clear();
    hideTooltip();
  }).on('click', function() {
    if (value === null) {
      showPopup('NIL pointer', 'A diagonal slash means no array index is stored in this pointer field. It marks the beginning or end of a linked chain.');
    } else {
      showPopup('Pointer field', 'The number ' + value + ' is interpreted as an index into the same parallel arrays. The record does not need to be adjacent to the current record.');
    }
  });
}

function hoverPointer(col, row, value, field) {
  hoverGroup.clear();
  if (value === null) {
    hoverGroup.rect(colW - 10, rowH - 10).move(colX(col) + 5, tableY + row * rowH + 5)
      .fill('none').stroke({ color: COLORS.cyan, width:4 });
    hoverGroup.circle(15).center(colX(col) + colW - 16, tableY + row * rowH + 15)
      .fill('#fff').stroke({ color: COLORS.cyan, width:3 });
  } else {
    hoverGroup.rect(colW - 8, tableH - 8).move(colX(value) + 4, tableY + 4)
      .fill({ color: COLORS.cyan, opacity:0.08 }).stroke({ color: COLORS.cyan, width:4 });
    hoverGroup.line(cellCenterX(col), cellCenterY(row), cellCenterX(value), tableY - 7)
      .stroke({ color: COLORS.cyan, width:3, dasharray:'6 5', linecap:'round' });
    hoverGroup.circle(12).center(cellCenterX(value), tableY - 7).fill(COLORS.cyan);
  }
}

function drawChangeHighlights(g, data) {
  if (currentState === 'initial') return;
  for (var i = 0; i < data.changes.length; i++) {
    var c = data.changes[i];
    if (c.kind === 'cell') {
      g.rect(colW - 12, rowH - 12)
        .move(colX(c.col) + 6, tableY + c.row * rowH + 6)
        .fill({ color: COLORS.gold, opacity:0.13 })
        .stroke({ color: COLORS.gold, width:4 });
    } else if (c.kind === 'head') {
      var p = headPos[c.id];
      g.rect(p.size + 12, p.size + 12).move(p.x - 6, p.y - 6)
        .fill('none').stroke({ color: COLORS.gold, width:5 });
    }
  }
}

function chainFor(headId, data) {
  var order = [], seen = {};
  var idx = data.heads[headId];
  while (idx != null && data.records[idx] && !seen[idx]) {
    order.push(idx);
    seen[idx] = true;
    idx = data.records[idx].next;
  }
  return order;
}

function drawArrow(g, x1, x2, color) {
  var y0 = tableY + tableH + 5, yb = 371;
  g.polyline([[x1, y0], [x1, yb], [x2, yb], [x2, y0]])
    .fill('none').stroke({ color: color, width:4, linecap:'round', linejoin:'round' });
  g.polygon([[x2, y0 - 3], [x2 - 8, y0 + 13], [x2 + 8, y0 + 13]]).fill(color);
}

function traceList(id, popupAlreadyHandled) {
  activeHead = id;
  traceGroup.clear();
  var data = getData(currentState);
  var order = chainFor(id, data);
  var color = id === 'free' ? '#111' : (id === 'L1' ? '#6d93ff' : '#7a5a00');

  var p = headPos[id];
  traceGroup.rect(p.size + 12, p.size + 12).move(p.x - 6, p.y - 6)
    .fill('none').stroke({ color: COLORS.gold, width:5 });

  for (var i = 0; i < order.length; i++) {
    var col = order[i];
    traceGroup.rect(colW - 10, tableH - 10).move(colX(col) + 5, tableY + 5)
      .fill({ color: COLORS.gold, opacity:0.20 }).stroke({ color: COLORS.gold, width:4 });
    traceGroup.circle(28).center(cellCenterX(col), tableY - 17).fill('#fff')
      .stroke({ color: COLORS.gold, width:3 });
    centeredText(traceGroup, i + 1, cellCenterX(col), tableY - 17, 18, '#000', false)
      .font({ weight:'bold' });
  }
  for (i = 0; i < order.length - 1; i++) {
    drawArrow(traceGroup, cellCenterX(order[i]), cellCenterX(order[i + 1]), color);
  }
}

function renderAll() {
  draw.clear();
  var data = getData(currentState);

  var base = draw.group();
  drawHeads(base, data);
  drawTable(base, data);

  var changeGroup = draw.group();
  drawChangeHighlights(changeGroup, data);

  traceGroup = draw.group();
  hoverGroup = draw.group();

  if (activeHead) traceList(activeHead, false);

  var readout = document.getElementById('stateReadout');
  if (readout) readout.textContent = 'state: ' + currentState;
}

function setAllocationState(state) {
  currentState = state;
  activeHead = null;
  renderAll();
}

function trigger_allocationFreeStep() {
  if (currentState === 'initial') setAllocationState('allocate 10 to L1');
  else if (currentState === 'allocate 10 to L1') setAllocationState('free 9 from L2');
  else setAllocationState('initial');

  for (var i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.allocationFreeStep === currentState) {
      currentStep = i;
      updateStepUI(false);
      break;
    }
  }
}

function updateStepUI(applyState) {
  var step = demoSteps[currentStep];
  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + ' / ' + demoSteps.length + ' — ' + step.title;
  if (applyState) setAllocationState(step.state.allocationFreeStep);
  if (currentStep === 1) {
    traceList('L2', false);
  }
}

function nextStep() {
  currentStep = Math.min(demoSteps.length - 1, currentStep + 1);
  updateStepUI(true);
}

function prevStep() {
  currentStep = Math.max(0, currentStep - 1);
  updateStepUI(true);
}

renderAll();
updateStepUI(false);
window.__markRendered();
// @FIGURE_CODE_END

